import json, random, subprocess, sys, time
CAND='/workspace/submission/main.py'

def build(kind, seed=0):
    rng=random.Random(seed)
    if kind=='wide64':
        nodes=['n%d'%i for i in range(64)]
        caps={n:1 for n in nodes}
        paths=[rng.sample(nodes,9) for _ in range(22)]
    elif kind=='overlap':
        nodes=['n%d'%i for i in range(8)]
        caps={n:2 for n in nodes}
        paths=[rng.sample(nodes,4) for _ in range(22)]
    elif kind=='half':
        nodes=['n0','n1']
        caps={'n0':11,'n1':11}
        paths=[['n0','n1']]*22
    elif kind=='bigbenefit':
        nodes=['n%d'%i for i in range(5)]
        caps={n:4 for n in nodes}
        paths=[rng.sample(nodes,3) for _ in range(22)]
    elif kind=='pinnedheavy':
        nodes=['n%d'%i for i in range(6)]
        caps={n:3 for n in nodes}
        paths=[rng.sample(nodes,2) for _ in range(22)]
    flows=[]; offers={}
    for i in range(22):
        fid='f%02d'%i
        H=8; kinds='QT'+'K'*5+'D'
        tmpl=('%02x'%(i%8))*8
        flows.append(dict(id=fid,path=paths[i],template=tmpl,kinds=kinds))
        # TTL must exceed the number of switches
        hdr=bytearray(bytes.fromhex(tmpl)); hdr[0]=i%8; hdr[1]=min(255,len(paths[i])+2)
        offers[fid]=[dict(header=bytes(hdr).hex(),count=rng.randint(1,10**6))]
    pinned=[f['id'] for f in flows[:3]]
    return dict(mode='plan',capacities=caps,flows=flows,warmup=0,pinned=pinned,offers=offers)

for kind in ['wide64','overlap','half','bigbenefit','pinnedheavy']:
    worst=0; res=''
    for seed in range(6):
        req=build(kind,seed)
        t0=time.time()
        out=subprocess.run([sys.executable,'-I','-B',CAND],input=json.dumps(req)+'\n',text=True,capture_output=True)
        dt=time.time()-t0
        if dt>worst: worst=dt; res=out.stdout.strip()[:100]
    print('%-12s worst %.2fs %s' % (kind,worst,res))
